std::vector<std::vector<int>> holeBoundaries;
for (auto it = poly.facets_begin(); it != poly.facets_end(); ++it) {
    if (it->is_hole()) {
        holeBoundaries.push_back(std::vector<int>());
        for (auto vit = it->vertices_begin(); vit != it->vertices_end(); ++vit) {
            holeBoundaries.back().push_back(vit->id());
        }
    }
}

for (const auto& boundary : holeBoundaries) {
    std::vector<std::vector<int>> triangles;
    CGAL::convex_hull_2(boundary.begin(), boundary.end(), std::back_inserter(triangles));
    for (const auto& triangle : triangles) {
        poly.make_hole(triangle);
    }
}

poly.normalize_border();

